frappe.ui.form.on('Test PO', {
    refresh(frm) {
        if (frm.doc.docstatus === 1){
            frm.add_custom_button("test Po",function(){
                frappe.call({
                    method : "test_script",
                    args :{
                        doc_name : frm.doc.name
                    },
                    callback:function(r){
                        console.log(r.message)
                        if (r.message){
                            let pr = frappe.model.get_new_doc("Test PR")
                            Object.assign(pr, r.message)
                            
                            pr.items=[]
                            
                            if (r.message.items){
                                r.message.items.forEach(row =>{
                                    let child = frappe.model.add_child(pr,"Test PR Items","items")
                                    Object.assign(child, row)
                                })
                            }
                            
                            frappe.set_route("Form", pr.doctype,pr.name)
                        }
                    }
                })
            })
        }
        
    },
});

frappe.ui.form.on('Customer Feedback', {
	refresh(frm) {
		const pending = (frm.doc.action_items || []).filter(row => !row.done).length;
		console.log(pending)
// 		frm.set_intro(`Pending Actions: ${pending_count}` , pending ? 'orange':'green');
        frm.set_intro(`pending :: ${pending}`, pending ? 'orange':'green')

	},

	onload(frm){
	    if(!frm.doc.feedback_date){
	        frm.set_value("feedback_date",frappe.datetime.get_today())
	    }
	},

	rating(frm){
	    if(frm.doc.rating === '1' || frm.doc.rating === '2'){
	        frappe.msgprint({
	            "title":"Low rating detected – please addd detailed feedback.",
	            "indicator" : "orange",
	            "message":__("Low rating detected – please addd detailed feedback."),
	        })
	    }
	},

	validate(frm){
	    if(frm.doc.rating && (!frm.doc.feedback_text)){
	        frappe.throw(__("Feedback is necessary"))
	    }
	},

	customer(frm){
	    if(frm.doc.customer){
	     frappe.db.get_value(
	            "Customer",
	            frm.doc.customer,
	            "mobile_no",
	            (r) => {
	                frm.set_df_property(
	                       "customer",
	                       "description",
	                       'Mobile:'+ (r.mobile_no || 'N/A')
	                    )
	            }
	         )   
	    }
	},

	before_submit(frm) {
        const missing = frm.doc.action_items.filter(
            row => !row.due_date
        );
        if (missing.length) {
            frappe.throw('All action items must have a due date.');
        }
        },
        action_items_add(frm) { updateTitle(frm); },
        action_items_remove(frm) { updateTitle(frm); 

    },

    custom_due_date(frm) {
        (frm.doc.action_items || []).forEach(row => {
            if (!row.due_date) {
                // console.log("hii")
                frappe.model.set_value(row.doctype,row.name,"due_date",frm.doc.custom_due_date)
            }
        });
    }
})


