frappe.ui.form.on('Sales Order', {
	refresh(frm) {
		// your code here
	},
	customer(frm){
	  if(!frm.doc.customer || !frm.doc.company){
	      return
	  }
	  else{
	      console.log("in call")
	      frappe.call({
	          method:'my_app.my_app.api.fetch_customer_credit',
	          args:{
	              'company':frm.doc.company,
	              'customer':frm.doc.customer,
	          },
	          callback:function(r){
	              console.log(r.message)

	              if(r.message){
	                  let credit = r.message.credit
	                  let outstanding = r.message.outstanding[0].outstanding
	                  frm.set_value("custom_customer_credit_limit",credit)
	                  let available_credit = credit - outstanding
	                  frm.set_value("custom_available_credit",available_credit)
	               //   frm.refresh_field("custom_customer_credit_limit")
	               //   frm.refresh_field("custom_available_credit")
	              }
	          }
	      })
	  }
	},

	custom_customer_credit_limit(frm){
	    if(frm.doc.custom_customer_credit_limit > 0){
	        frm.get_field('custom_customer_credit_limit').$wrapper.css('background-color', '#ffcccc')
	    }
	}
})

frappe.ui.form.on('Quick Order', {
	refresh(frm) {
	    frm.add_custom_button("Add SO Items", function(){
	       // frappe.prompt([{....}], (r)=>{

	       //})

	        frappe.prompt([{
	            'fieldname': 'so',
	            'fieldtype': 'Link',
	            'label': 'Sales Order',
	            'reqd': 1,
	            'options':"Sales Order"

	        }],(r)=>{
	            frappe.db.get_doc("Sales Order",r.so).then((r)=>{
	                console.log(r)
	                r.items.forEach(item=>{
	                    let child = frm.add_child('quick_order_items')
	                    child.item_code = item.item_code
	                    child.item_name = item.item_code
	                    child.uom = item.uom
	                    child.rate = item.rate
	                    child.qty = item.qty
	                    child.amount = item.amount
	                })
	                frm.refresh_field('quick_order_items')
	               // frm.trigger("calculate_amount")

	            })
	        })

	    })

		frm.trigger("calculate_amount")
	},

	calculate_amount(frm){
	    console.log("calculating")
	  let sum = 0;
	  (frm.doc.quick_order_items ||[]).forEach(r =>{
	      sum= sum + r.amount
	  })
	  frm.set_value("toatal_amount",sum)


	},

	quick_order_items_remove(frm){
	    frm.trigger("calculate_amount")
	},
	quick_order_items_add(frm){
	    frm.trigger("calculate_amount")
	}
})

frappe.ui.form.on('Quick Items', {
	refresh(frm) {
		// your code here
	},
	item_code(frm,cdt,cdn){
	  let row = locals[cdt][cdn]  
	  if (row.item_code){
	      frappe.db.get_value("Item", row.item_code,fields=["item_name","valuation_rate","stock_uom"]).then(r=>{
	          r=r.message
	          frappe.model.set_value(cdt,cdn,"item_name",r.item_name)
	          frappe.model.set_value(cdt,cdn,"rate",r.valuation_rate)
	          frappe.model.set_value(cdt,cdn,"uom",r.stock_uom)
	      })
	  }
	},

	qty(frm,cdt,cdn){
	    let row = locals[cdt][cdn]
	    frappe.model.set_value(cdt,cdn,"amount",(row.qty*row.rate)||0)    
	},

	rate(frm,cdt,cdn){
	    let row = locals[cdt][cdn]
	    frappe.model.set_value(cdt,cdn,"amount",(row.qty*row.rate)||0)    
	},
	amount(frm,cdt,cdn){
	    frm.trigger("calculate_amount")
	},

})

